function verify_ultrametric(n):
    V <- all binary vectors of length n
    triangle  <- TRUE
    isosceles <- TRUE
    for x in V:
        for y in V:
            s <- x XOR y
            if tprof(s) > max(tprof(x), tprof(y)):
                triangle <- FALSE
            if tprof(x) != tprof(y) and tprof(s) != max(tprof(x), tprof(y)):
                isosceles <- FALSE
    return (triangle, isosceles)

